mapper.select:
SELECT DISTINCT q.quiz_id, q.question_text, q.question_image_url, q.answer, q.explanation, q.difficulty, q.source, q.created_at, q.updated_at FROM quizzes q LEFT JOIN quiz_tags qt ON qt.quiz_id = q.quiz_id LEFT JOIN history_tags ht ON ht.tag_id = qt.tag_id
AND ( q.question_text LIKE CONCAT('%', #{keyword}, '%') OR q.source LIKE CONCAT('%', #{keyword}, '%') )
AND q.difficulty = #{difficulty}
AND ht.tag_name LIKE CONCAT('%', #{tagName}, '%')
AND ht.tag_type = #{tagType}
ORDER BY q.quiz_id LIMIT #{limit} OFFSET #{offset}

SELECT quiz_id, question_text, question_image_url, answer, explanation, difficulty, source, created_at, updated_at
FROM quizzes
WHERE quiz_id = #{quizId}
